sys_ui_page.client_script:
addLoadEvent(function () {

    console.log("Result Modal Loaded ✅");

    var summary = null;

    // ✅ Try both methods (safe fallback)
    try {
        summary = GlideModal.get().getPreference('summary');
    } catch (e) {}

    if (!summary && window.dialogArguments) {
        summary = window.dialogArguments.summary;
    }

    console.log("SUMMARY RECEIVED:", summary);

    if (summary) {
        document.getElementById("resultText").innerText = summary;
    } else {
        document.getElementById("resultText").innerText = "No summary received.";
    }

});
